import*as cheerio from"cheerio";import{globby}from"globby";import{createCipheriv,createHash,createHmac,randomBytes}from"node:crypto";import{promises as fs}from"node:fs";import pLimit from"p-limit";import{fileURLToPath}from"url";const META_TAG_NAME="x-mail-obf";const CONFIG_META_TAG_NAME="x-mail-obf-config";const KEY_DERIVATION_CONTEXT="functionfly/mail-obfuscation/v2:";function generateUserKey(){return randomBytes(32).toString("hex")}function generateUserSalt(length){const bytes=randomBytes(length);return bytes.toString("base64url").slice(0,length)}function deriveMetaKey(salt){return createHash("sha256").update(KEY_DERIVATION_CONTEXT+salt).digest()}function createIntegrityChecksum(data,key){return createHmac("sha256",key).update(data).digest("hex")}function aesEncrypt(plaintext,key){const iv=randomBytes(12);const cipher=createCipheriv("aes-256-gcm",key,iv);const encrypted=Buffer.concat([cipher.update(plaintext,"utf8"),cipher.final()]);const authTag=cipher.getAuthTag();return Buffer.concat([iv,encrypted,authTag]).toString("base64url")}const defaultAllowedTags=["h1","h2","h3","h4","h5","h6","p","span","a","label","ul","ol","li","strong","b","em","i","div","section","article","td","th","blockquote"];export default function astroMailObfuscation(userOptions={}){const userKey=userOptions.userKey||generateUserKey();const userSalt=userOptions.userSalt||generateUserSalt(12);const keyHash=createHash("sha256").update(userKey+userSalt).digest();const options={fallbackText:userOptions.fallbackText||"[PROTECTED!]",userKey:userKey,userSalt:userSalt,allowedTags:mergeAllowedTags(userOptions.allowedTags),concurrencyLimit:userOptions.concurrencyLimit||5,encryptedMeta:userOptions.encryptedMeta!==false,randomMethod:userOptions.randomMethod??true};return{name:"@functionfly/astro-mail-obfuscation",hooks:{"astro:config:setup":({injectScript:injectScript})=>{try{const scriptUrl=new URL("./scripts/client.js",import.meta.url).href;injectScript("page",`import "${scriptUrl}";`)}catch(err){console.error("[@functionfly/astro-mail-obfuscation] Failed to inject script.",err);throw err}},"astro:build:done":async({dir:dir})=>{const outDir=fileURLToPath(dir);const htmlFiles=await globby("**/*.html",{cwd:outDir,absolute:true});const limit=pLimit(options.concurrencyLimit);const failures=[];const tasks=htmlFiles.map(file=>limit(async()=>{const failure=await processHtmlFile(file,options,keyHash);if(failure)failures.push(failure)}));await Promise.all(tasks);if(failures.length>0){throw new Error(`[@functionfly/astro-mail-obfuscation] Failed to obfuscate ${failures.length} page(s):\n${failures.slice(0,10).join("\n")}`)}console.log(`[@functionfly/astro-mail-obfuscation] Completed (${htmlFiles.length} page(s)).`)}}}}function mergeAllowedTags(userTags){const combinedTags=new Set;defaultAllowedTags.forEach(tag=>combinedTags.add(tag.toLowerCase()));if(userTags){userTags.forEach(tag=>combinedTags.add(tag.toLowerCase()))}return Array.from(combinedTags)}async function processHtmlFile(filePath,options,keyHash){try{const html=await fs.readFile(filePath,"utf-8");const modifiedHtml=await modifyHtml(html,options,keyHash);await fs.writeFile(filePath,modifiedHtml,"utf-8");return undefined}catch(err){const message=err instanceof Error?err.message:String(err);console.error(`[@functionfly/astro-mail-obfuscation] Error processing file ${filePath}: ${message}`);return`${filePath}: ${message}`}}async function modifyHtml(html,options,keyHash){const $=cheerio.load(html);const selector="[data-obfuscation]";$(selector).each((_,element)=>{const $el=$(element);const tagName=$el[0].tagName.toLowerCase();if(!options.allowedTags.includes(tagName)){console.warn(`[@functionfly/astro-mail-obfuscation] <${tagName}> is not allowed. Skipping.`);return}const href=$el.attr("href")||"";const type=$el.attr("data-obfuscation")||"";let method;if(options.randomMethod){method=(Math.floor(Math.random()*3)+1).toString()}else{const validTypes=["1","2","3"];method=validTypes.includes(type)?type:"1"}const content=$el.html()||"";const encryptedContent=encryptContent(content,method,keyHash);const encryptedHref=href?encryptContent(href,method,keyHash):null;if(encryptedContent){$el.empty();$el.append(`<noscript>${options.fallbackText}</noscript>`);$el.attr("data-mobfuscated",encryptedContent);$el.attr("data-method",method);if(encryptedHref){$el.attr("data-href",encryptedHref);$el.removeAttr("href")}}else{console.error("[@functionfly/astro-mail-obfuscation] Encryption failed for element")}});if($("[data-mobfuscated]").length){const metaContent=buildMetaContent(options.userSalt,options.encryptedMeta,keyHash);$("head").append(`<meta name="${META_TAG_NAME}" content="${metaContent}">`);const config=JSON.stringify({encrypted:options.encryptedMeta});$("head").append(`<meta name="${CONFIG_META_TAG_NAME}" content='${config}'>`)}return $.html()}export function buildMetaContent(salt,encryptedMeta,keyHash){const keyHex=keyHash.toString("hex");if(encryptedMeta){const payload=aesEncrypt(keyHex,deriveMetaKey(salt));const checksum=createIntegrityChecksum(payload,keyHex);return`v2:${payload}:${checksum}:${salt}`}const checksum=createIntegrityChecksum(keyHex,keyHex);return`v1:${keyHex}:${checksum}:${salt}`}export function encryptContent(content,method,key){if(!content||!key)return undefined;try{const contentBuffer=Buffer.from(content,"utf8");const encrypted=Buffer.alloc(contentBuffer.length);for(let i=0;i<contentBuffer.length;i++){const keyByte=key[i%key.length];switch(method){case"1":encrypted[i]=contentBuffer[i]^keyByte;break;case"2":encrypted[i]=contentBuffer[i]^keyByte^i&255;break;case"3":const saltMix=key[(i*7+13)%key.length];encrypted[i]=contentBuffer[i]^keyByte^saltMix;break;default:encrypted[i]=contentBuffer[i]^keyByte}}return encrypted.toString("base64url")}catch(err){console.error(`[@functionfly/astro-mail-obfuscation] Encryption error in method ${method}.`,err);return undefined}}